const MONTHS={1:"Jan",2:"Feb",3:"Mar",4:"Apr",5:"May",6:"Jun",7:"Jul",8:"Aug"};
const norm=s=>String(s??"").trim().toLowerCase();
const lineFlag=v=>{
  const s=norm(v);
  if(["1","yes","y","true","registered","register","ลงทะเบียน"].includes(s))return true;
  if(["0","no","n","false","not registered","not register","unregistered","ยังไม่ลงทะเบียน","ไม่ลงทะเบียน"].includes(s))return false;
  return false;
};

function hasLineIntent(text){
  const q=norm(text||"");
  return /line\s*register|line\s*registration|line\s*oa|line\s*reg|ลงทะเบียน\s*line|ลงทะเบียนไลน์|ไลน์\s*register|ไลน์\s*รีจิส/.test(q);
}
function hasMissionIntent(text){
  const q=norm(text||"");
  return /\bmission\b|join\s*mission|มิชชั่น|มิสชั่น/.test(q);
}
function asksUnregistered(text){
  const q=norm(text||"");
  return /ยังไม่ลงทะเบียน|ไม่ได้ลงทะเบียน|ไม่ลงทะเบียน|not\s*registered|unregistered/.test(q);
}
function asksStoreNames(text){
  const q=norm(text||"");
  return /ร้านไหน|รายชื่อ|ชื่อร้าน|ad\s*ไหน|dealer|top\s*\d*|list\s*\d*|ยอดซื้อสูง|ยอดสูง|มากสุด|สูงสุด/.test(q);
}

const num=x=>Number(x||0);
function mergedFilters(base={},o={}){
  const f={...base};
  for(const [k,v] of Object.entries(o||{})) if(v!==undefined&&v!==null&&v!==""&&v!=="all") f[k]=v;
  return f;
}

let _AD_MASTER_CACHE=null;

function buildADMaster(){
  if(_AD_MASTER_CACHE)return _AD_MASTER_CACHE;

  const meta=new Map();
  for(const x of ENTITY_ADS){
    const key=norm(x.distributor)+"\u0001"+norm(x.ad);
    if(!meta.has(key)){
      meta.set(key,{
        distributor:x.distributor,
        ad:x.ad,
        ad_code:(x.ad_code && x.ad_code!=="null") ? String(x.ad_code) : null,
        line_registered:!!x.line_registered
      });
    }else{
      const m=meta.get(key);
      if(!m.ad_code && x.ad_code && x.ad_code!=="null")m.ad_code=String(x.ad_code);
      m.line_registered=m.line_registered||!!x.line_registered;
    }
  }

  // Only current sell-out ADs are exposed in the analytical master.
  const sales=new Map();
  for(const r of DATA){
    const key=norm(r[0])+"\u0001"+norm(r[1]);
    if(!sales.has(key)){
      sales.set(key,{
        distributor:r[0], ad:r[1], status:r[2],
        qty:0, sales:0, months:new Set(), segments:new Map(), patterns:new Map()
      });
    }
    const x=sales.get(key);
    x.qty+=num(r[7]); x.sales+=num(r[8]);
    if(num(r[7])>0)x.months.add(Number(r[3]));
    const seg=r[5]||"Unknown", pat=r[6]||"Unknown";
    x.segments.set(seg,(x.segments.get(seg)||0)+num(r[7]));
    x.patterns.set(pat,(x.patterns.get(pat)||0)+num(r[7]));
  }

  const out=new Map();
  for(const [key,s] of sales){
    const m=meta.get(key);
    out.set(key,{
      distributor:s.distributor,
      ad:s.ad,
      ad_code:m?.ad_code||null,
      line_registered:m ? !!m.line_registered : false,
      line_source:m ? "ENTITY_ADS" : "No master match",
      status:s.status||null,
      qty:s.qty,
      sales:s.sales,
      purchasing_months:s.months.size,
      top_segment:[...s.segments.entries()].sort((a,b)=>b[1]-a[1])[0]?.[0]||null,
      top_pattern:[...s.patterns.entries()].sort((a,b)=>b[1]-a[1])[0]?.[0]||null
    });
  }

  _AD_MASTER_CACHE=out;
  return out;
}

function adMasterRecord(dist,ad){
  return buildADMaster().get(norm(dist)+"\u0001"+norm(ad))||null;
}

function storeLineRegistered(r){
  return adMasterRecord(r[0],r[1])?.line_registered===true;
}

function filteredRows(baseFilters={},overrides={}){
  const f=mergedFilters(baseFilters,overrides);
  return DATA.filter(r=>{
    if(f.distributor && f.distributor!=="all" && norm(r[0])!==norm(f.distributor))return false;
    if(f.month && f.month!=="all" && Number(r[3])!==Number(f.month))return false;
    // LINE registration is a dealer/store attribute, not a row attribute.
    // If any row for a dealer is registered, the whole dealer is treated as registered.
    if(f.line!==undefined && f.line!=="all"){
      const want=Number(f.line)===1;
      if(storeLineRegistered(r)!==want)return false;
    }
    if(f.segment && f.segment!=="all" && norm(r[5])!==norm(f.segment))return false;
    if(f.pattern && f.pattern!=="all" && norm(r[6])!==norm(f.pattern))return false;
    if(f.status && f.status!=="all" && norm(r[2])!==norm(f.status))return false;
    if(f.ad && f.ad!=="all" && !norm(r[1]).includes(norm(f.ad)))return false;
    if(f.ad_contains && !norm(r[1]).includes(norm(f.ad_contains)))return false;
    return true;
  });
}
function aggregate(rows,keyFn){
  const m=new Map();
  for(const r of rows){
    const k=keyFn(r); if(!m.has(k))m.set(k,{qty:0,sales:0,rows:0});
    const x=m.get(k);x.qty+=num(r[7]);x.sales+=num(r[8]);x.rows++;
  }
  return m;
}
function summary(rows){
  return {qty:rows.reduce((s,r)=>s+num(r[7]),0),sales:rows.reduce((s,r)=>s+num(r[8]),0),unique_ad:new Set(rows.map(r=>r[0]+"\u0001"+r[1])).size,rows:rows.length};
}
function topSegmentPattern(rows){
  const seg=aggregate(rows,r=>r[5]); const pat=aggregate(rows,r=>r[6]);
  const s=[...seg].sort((a,b)=>b[1].sales-a[1].sales)[0]; const p=[...pat].sort((a,b)=>b[1].sales-a[1].sales)[0];
  return {top_segment:s?.[0]||null,top_pattern:p?.[0]||null};
}

function adMetaFor(dist,ad){
  const master=adMasterRecord(dist,ad);
  if(master)return {
    distributor:master.distributor,
    ad:master.ad,
    ad_code:master.ad_code,
    line_registered:master.line_registered
  };
  const nd=norm(dist),na=norm(ad);
  const hits=ENTITY_ADS.filter(x=>norm(x.distributor)===nd && norm(x.ad)===na);
  if(!hits.length)return null;
  const best=hits.find(x=>x.ad_code&&x.ad_code!=="null")||hits[0];
  return best;
}
function adSalesMap(baseFilters={}){
  const rows=filteredRows(baseFilters,{month:"all",ad:"all"});
  const m=new Map();
  for(const r of rows){const k=norm(r[0])+"\u0001"+norm(r[1]);if(!m.has(k))m.set(k,{qty:0,sales:0});const x=m.get(k);x.qty+=num(r[7]);x.sales+=num(r[8]);}
  return m;
}
function adLookup(args,base){
  const q=norm(args.query||""); const f=args.filters||{}; const limit=Math.min(Math.max(Number(args.limit)||10,1),30); const sm=adSalesMap(base);
  let rows=ENTITY_ADS.filter(x=>{
    if(f.distributor&&f.distributor!=="all"&&norm(x.distributor)!==norm(f.distributor))return false;
    if(!q)return true;
    return norm(x.ad).includes(q)||norm(x.ad_code).includes(q)||norm(x.distributor).includes(q);
  });
  const uniq=new Map();
  for(const x of rows){const k=norm(x.distributor)+"\u0001"+norm(x.ad_code||x.ad);if(!uniq.has(k))uniq.set(k,x);}
  return [...uniq.values()].map(x=>{const s=sm.get(norm(x.distributor)+"\u0001"+norm(x.ad))||{qty:0,sales:0};return {...x,qty:s.qty,sales:s.sales};}).sort((a,b)=>b.sales-a.sales).slice(0,limit);
}
function productLookup(args){
  const q=norm(args.query||""); const limit=Math.min(Math.max(Number(args.limit)||15,1),40);
  return PRODUCT_CODES.filter(x=>!q||norm(x.cai).includes(q)||norm(x.item).includes(q)||norm(x.pattern).includes(q)).sort((a,b)=>b.sales-a.sales).slice(0,limit);
}
function adProductDetail(args){
  const aq=norm(args.ad_query||""); const pq=norm(args.product_query||""); const metric=args.metric==="qty"?"qty":"sales"; const limit=Math.min(Math.max(Number(args.limit)||20,1),50);
  let rows=AD_PRODUCTS.filter(x=>norm(x.ad).includes(aq)||norm(x.ad_code).includes(aq));
  if(args.filters?.distributor&&args.filters.distributor!=="all")rows=rows.filter(x=>norm(x.distributor)===norm(args.filters.distributor));
  if(pq)rows=rows.filter(x=>norm(x.cai).includes(pq)||norm(x.item).includes(pq)||norm(x.pattern).includes(pq));
  return rows.sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}
function productBuyers(args){
  const q=norm(args.query||""); const metric=args.metric==="qty"?"qty":"sales"; const limit=Math.min(Math.max(Number(args.limit)||20,1),50);
  const rows=AD_PRODUCTS.filter(x=>norm(x.cai).includes(q)||norm(x.item).includes(q)||norm(x.pattern).includes(q));
  const by=new Map();
  for(const x of rows){const k=x.distributor+"\u0001"+x.ad_code+"\u0001"+x.ad;if(!by.has(k))by.set(k,{distributor:x.distributor,ad_code:x.ad_code,ad:x.ad,qty:0,sales:0});const y=by.get(k);y.qty+=num(x.qty);y.sales+=num(x.sales);}
  return [...by.values()].sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}
function rankProductCodes(args){
  const metric=args.metric==="qty"?"qty":"sales"; const limit=Math.min(Math.max(Number(args.limit)||15,1),50); const q=norm(args.query||"");
  return PRODUCT_CODES.filter(x=>!q||norm(x.item).includes(q)||norm(x.pattern).includes(q)||norm(x.cai).includes(q)).sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}

function adMasterQuery(args,base){
  const q=norm(args.query||"");
  const limit=Math.min(Math.max(Number(args.limit)||20,1),50);
  let rows=[...buildADMaster().values()];

  const f=args.filters||{};
  if(f.distributor&&f.distributor!=="all")rows=rows.filter(x=>norm(x.distributor)===norm(f.distributor));
  if(f.status&&f.status!=="all")rows=rows.filter(x=>norm(x.status)===norm(f.status));
  if(args.line_status==="registered")rows=rows.filter(x=>x.line_registered);
  if(args.line_status==="not_registered")rows=rows.filter(x=>!x.line_registered);

  if(q){
    rows=rows.filter(x=>
      norm(x.ad).includes(q) ||
      norm(x.ad_code).includes(q) ||
      norm(x.distributor).includes(q)
    );
  }

  const metric=args.metric==="qty"?"qty":"sales";
  return rows.sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}

function adRankMart(args,base){
  const limit=Math.min(Math.max(Number(args.limit)||10,1),50);
  const metric=args.metric==="qty"?"qty":"sales";
  const f={...(args.filters||{})};

  // Apply transaction-level filters first, but LINE registration from AD master only.
  delete f.line;
  let rows=filteredRows(base,f);
  const by=new Map();

  for(const r of rows){
    const key=norm(r[0])+"\u0001"+norm(r[1]);
    if(!by.has(key)){
      const m=adMasterRecord(r[0],r[1]);
      by.set(key,{
        distributor:r[0],
        ad:r[1],
        ad_code:m?.ad_code||null,
        line_registered:m?.line_registered===true,
        status:r[2]||null,
        qty:0,
        sales:0,
        rows:[]
      });
    }
    const x=by.get(key);
    x.qty+=num(r[7]); x.sales+=num(r[8]); x.rows.push(r);
  }

  let out=[...by.values()];
  if(args.line_status==="registered")out=out.filter(x=>x.line_registered);
  if(args.line_status==="not_registered")out=out.filter(x=>!x.line_registered);

  if(args.query){
    const q=norm(args.query);
    out=out.filter(x=>norm(x.ad).includes(q)||norm(x.ad_code).includes(q)||norm(x.distributor).includes(q));
  }

  return out
    .map(x=>{
      const tsp=topSegmentPattern(x.rows);
      const {rows,...rest}=x;
      return {...rest,...tsp};
    })
    .sort((a,b)=>b[metric]-a[metric])
    .slice(0,limit);
}

function productMasterQuery(args){
  const q=norm(args.query||"");
  const metric=args.metric==="qty"?"qty":"sales";
  const limit=Math.min(Math.max(Number(args.limit)||20,1),50);
  return PRODUCT_CODES
    .filter(x=>!q||norm(x.cai).includes(q)||norm(x.item).includes(q)||norm(x.pattern).includes(q))
    .sort((a,b)=>b[metric]-a[metric])
    .slice(0,limit);
}

function adProductMart(args){
  const aq=norm(args.ad_query||"");
  const pq=norm(args.product_query||"");
  const metric=args.metric==="qty"?"qty":"sales";
  const limit=Math.min(Math.max(Number(args.limit)||20,1),60);

  let rows=AD_PRODUCTS.filter(x=>{
    const adHit=!aq||norm(x.ad).includes(aq)||norm(x.ad_code).includes(aq);
    const productHit=!pq||norm(x.cai).includes(pq)||norm(x.item).includes(pq)||norm(x.pattern).includes(pq);
    return adHit&&productHit;
  });

  if(args.filters?.distributor&&args.filters.distributor!=="all"){
    rows=rows.filter(x=>norm(x.distributor)===norm(args.filters.distributor));
  }

  return rows.sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}

function productBuyerMart(args){
  const q=norm(args.product_query||"");
  const metric=args.metric==="qty"?"qty":"sales";
  const limit=Math.min(Math.max(Number(args.limit)||20,1),50);
  let rows=AD_PRODUCTS.filter(x=>!q||norm(x.cai).includes(q)||norm(x.item).includes(q)||norm(x.pattern).includes(q));

  const by=new Map();
  for(const x of rows){
    const key=norm(x.distributor)+"\u0001"+norm(x.ad);
    if(!by.has(key)){
      const m=adMasterRecord(x.distributor,x.ad);
      by.set(key,{
        distributor:x.distributor,
        ad:x.ad,
        ad_code:m?.ad_code||x.ad_code||null,
        line_registered:m?.line_registered===true,
        qty:0,
        sales:0
      });
    }
    const y=by.get(key);
    y.qty+=num(x.qty); y.sales+=num(x.sales);
  }

  let out=[...by.values()];
  if(args.line_status==="registered")out=out.filter(x=>x.line_registered);
  if(args.line_status==="not_registered")out=out.filter(x=>!x.line_registered);
  return out.sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}

function salesSummary(args,base){
  const rows=filteredRows(base,args.filters||{}); const s=summary(rows);
  const months=[...aggregate(rows,r=>r[3])].map(([m,x])=>({month:Number(m),label:MONTHS[m],qty:x.qty,sales:x.sales})).sort((a,b)=>a.month-b.month);
  const dists=[...aggregate(rows,r=>r[0])].map(([name,x])=>({distributor:name,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales);
  const segments=[...aggregate(rows,r=>r[5])].map(([name,x])=>({segment:name,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales);
  return {...s,months,distributors:dists,segments};
}
function rankAds(args,base){
  const rows=filteredRows(base,args.filters||{}); const metric=args.metric==="qty"?"qty":"sales"; const limit=Math.min(Math.max(Number(args.limit)||10,1),50);
  const by=new Map();
  for(const r of rows){const k=r[0]+"\u0001"+r[1];if(!by.has(k))by.set(k,{distributor:r[0],ad:r[1],qty:0,sales:0,rows:[]});const x=by.get(k);x.qty+=num(r[7]);x.sales+=num(r[8]);x.rows.push(r);}
  return [...by.values()].map(x=>{const meta=adMetaFor(x.distributor,x.ad);return {...x,ad_code:meta?.ad_code||null,line_registered:meta?.line_registered??null,...topSegmentPattern(x.rows)};}).sort((a,b)=>b[metric]-a[metric]).slice(0,limit).map(({rows,...x})=>x);
}
function rankPatterns(args,base){
  const rows=filteredRows(base,args.filters||{});const metric=args.metric==="qty"?"qty":"sales";const limit=Math.min(Math.max(Number(args.limit)||10,1),50);
  const by=new Map();for(const r of rows){const k=r[6];if(!by.has(k))by.set(k,{pattern:k,segment:r[5],qty:0,sales:0});const x=by.get(k);x.qty+=num(r[7]);x.sales+=num(r[8]);}
  return [...by.values()].sort((a,b)=>b[metric]-a[metric]).slice(0,limit);
}
function monthlyTrend(args,base){
  const rows=filteredRows(base,{...(args.filters||{}),month:"all"}); const by=aggregate(rows,r=>r[3]);
  return [...by].map(([m,x])=>({month:Number(m),label:MONTHS[m],qty:x.qty,sales:x.sales})).sort((a,b)=>a.month-b.month);
}
function compareMonths(args,base){
  const ma=Number(args.month_a),mb=Number(args.month_b); const metric=args.metric==="qty"?"qty":"sales"; const group=args.group_by||"ad"; const limit=Math.min(Math.max(Number(args.limit)||15,1),50);
  const baseF={...(args.filters||{}),month:"all"}; const rows=filteredRows(base,baseF);
  const keyFn=r=>group==="pattern"?r[6]:group==="distributor"?r[0]:group==="segment"?r[5]:(r[0]+"\u0001"+r[1]);
  const a=aggregate(rows.filter(r=>Number(r[3])===ma),keyFn), b=aggregate(rows.filter(r=>Number(r[3])===mb),keyFn);
  const keys=new Set([...a.keys(),...b.keys()]); const out=[];
  for(const k of keys){const av=a.get(k)?.[metric]||0,bv=b.get(k)?.[metric]||0; const delta=bv-av; const pct=av?delta/av*100:(bv?null:0); let label=k,dist=null;if(group==="ad"){[dist,label]=k.split("\u0001");}
    out.push({label,distributor:dist,month_a:ma,value_a:av,month_b:mb,value_b:bv,delta,pct_change:pct});}
  const direction=args.direction||"decline"; out.sort((x,y)=>direction==="growth"?y.delta-x.delta:x.delta-y.delta); return out.slice(0,limit);
}
function bigRetail(args,base){
  const rows=filteredRows(base,{...(args.filters||{}),status:"Big Retail"}); const s=summary(rows); const seg=[...aggregate(rows,r=>r[5])].map(([segment,x])=>({segment,qty:x.qty,sales:x.sales,sales_pct:s.sales?x.sales/s.sales*100:0,qty_pct:s.qty?x.qty/s.qty*100:0})).sort((a,b)=>b.sales-a.sales);
  return {...s,segments:seg,top_ads:rankAds({filters:{...(args.filters||{}),status:"Big Retail"},metric:args.metric||"sales",limit:args.limit||15},base)};
}
function storeDetail(args,base){
  const q=args.name||""; const rows=filteredRows(base,{...(args.filters||{}),month:"all",ad_contains:q});
  const byStore=new Map(); for(const r of rows){const k=r[0]+"\u0001"+r[1];if(!byStore.has(k))byStore.set(k,[]);byStore.get(k).push(r);}
  return [...byStore].slice(0,8).map(([k,rs])=>{const [dist,ad]=k.split("\u0001");const s=summary(rs);const meta=adMetaFor(dist,ad);return {distributor:dist,ad,ad_code:meta?.ad_code||null,line_registered:meta?.line_registered??null,...s,monthly:[...aggregate(rs,r=>r[3])].map(([m,x])=>({month:Number(m),label:MONTHS[m],qty:x.qty,sales:x.sales})).sort((a,b)=>a.month-b.month),segments:[...aggregate(rs,r=>r[5])].map(([segment,x])=>({segment,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales),patterns:[...aggregate(rs,r=>r[6])].map(([pattern,x])=>({pattern,qty:x.qty,sales:x.sales})).sort((a,b)=>b.sales-a.sales).slice(0,20)};});
}
function registrationSummary(args,base){
  const rows=adRankMart({
    filters:args.filters||{},
    metric:"sales",
    limit:5000
  },base);

  const reg=rows.filter(x=>x.line_registered);
  const no=rows.filter(x=>!x.line_registered);
  const sum=a=>({
    unique_ad:a.length,
    qty:a.reduce((s,x)=>s+num(x.qty),0),
    sales:a.reduce((s,x)=>s+num(x.sales),0)
  });

  return {
    source:"AD_MASTER + SALES_FACT",
    registered_store_count:reg.length,
    not_registered_store_count:no.length,
    registered:sum(reg),
    not_registered:sum(no),
    top_not_registered:no.slice().sort((a,b)=>b.sales-a.sales).slice(0,20),
    top_registered:reg.slice().sort((a,b)=>b.sales-a.sales).slice(0,20)
  };
}

function lineUnregisteredStores(args,base){
  return adRankMart({
    filters:args.filters||{},
    line_status:"not_registered",
    metric:args.metric||"sales",
    limit:args.limit||10
  },base);
}
function percentileMedian(a){const x=a.filter(Number.isFinite).sort((a,b)=>a-b);if(!x.length)return 0;const m=Math.floor(x.length/2);return x.length%2?x[m]:(x[m-1]+x[m])/2;}
function sizeTier(q){q=Number(q||0);if(q<500)return null;if(q<1500)return {key:"small",label:"Small",range:"500-1,499"};if(q<5000)return {key:"medium",label:"Medium",range:"1,500-4,999"};return {key:"large",label:"Large",range:"5,000+"};}
function selfStore(name,dist){const n=norm(name),d=norm(dist);if(n.includes("หน้าร้าน"))return true;if(d==="epb"&&(n.includes("เอกไพบูลย์")||n.includes("ekpaiboon")))return true;if(d==="nky"&&(n.includes("นครยาง")||n.includes("n.yang")))return true;if(d==="sompol"&&n.includes("สมพล"))return true;if(d==="mgp"&&(n.includes("my megapart")||n.includes("เมกาพาร์ท")))return true;if(d==="rty"&&(n.includes("rty")||n.includes("ราชา")))return true;return false;}
function caiOpportunities(args,base){
  const all=filteredRows(base,{month:"all",line:"all",segment:"all",pattern:"all",ad:"all"}); const totalQty=aggregate(all,r=>r[0]+"\u0001"+r[1]);
  const filter=args.filters||{}; const limit=Math.min(Math.max(Number(args.limit)||15,1),40); const out=[];
  for(const g of CAI_PAIR_GROUPS){if(filter.segment&&filter.segment!=="all"&&norm(g.segment)!==norm(filter.segment))continue;if(filter.pattern&&filter.pattern!=="all"&&norm(g.pattern)!==norm(filter.pattern))continue;
    const peers=(g.dealers||[]).filter(d=>!selfStore(d.name,d.dist));
    for(const d of peers){if(filter.distributor&&filter.distributor!=="all"&&norm(d.dist)!==norm(filter.distributor))continue;if(filter.ad&&filter.ad!=="all"&&!norm(d.name).includes(norm(filter.ad)))continue;const dk=d.dist+"\u0001"+d.name;const tq=totalQty.get(dk)?.qty||0;const tier=sizeTier(tq);if(!tier)continue;const mix=num(d.totalQty)/tq*100;
      const same=peers.filter(p=>!(p.dist===d.dist&&p.name===d.name)).map(p=>{const pk=p.dist+"\u0001"+p.name;const q=totalQty.get(pk)?.qty||0;return {p,q,t:sizeTier(q)};}).filter(x=>x.t?.key===tier.key&&x.q>0);if(same.length<2)continue;const peerMix=percentileMedian(same.map(x=>num(x.p.totalQty)/x.q*100));if(peerMix<=mix)continue;const benchmark=tq*peerMix/100,gap=benchmark-num(d.totalQty);if(gap<4)continue;out.push({distributor:d.dist,ad:d.name,size_tier:tier.label,ytd_qty:tq,pattern:g.pattern,segment:g.segment,front:g.frontSize,rear:g.rearSize,current_pair_qty:num(d.totalQty),current_mix_pct:mix,peer_count:same.length,peer_mix_pct:peerMix,benchmark_qty:benchmark,gap_qty:gap,vehicle:(g.topModels||[])[0]||null});}
  }
  return out.sort((a,b)=>b.gap_qty-a.gap_qty).slice(0,limit);
}
function missionSummary(args){
  if(!MISSION_DATA.length)return {available:false}; let rows=MISSION_DATA; const f=args.filters||{}; if(f.distributor&&f.distributor!=="all")rows=rows.filter(x=>norm(x.distributor)===norm(f.distributor)); if(f.search)rows=rows.filter(x=>norm([x.storeName,x.selloutADName,x.adCode].join(" ")).includes(norm(f.search)));
  return {available:true,stores:rows.length,registered:rows.filter(x=>x.missionRegistered).length,not_registered:rows.filter(x=>!x.missionRegistered).length,matched:rows.filter(x=>x.matchBy!=="Not matched").length,top_not_registered:rows.filter(x=>!x.missionRegistered&&x.matchBy!=="Not matched").sort((a,b)=>num(b.ytdValue)-num(a.ytdValue)).slice(0,20).map(x=>({distributor:x.distributor,ad_code:x.adCode,store:x.selloutADName||x.storeName,ytd_value:x.ytdValue,ytd_qty:x.ytdQty,line_registered:x.lineRegistered,size:x.sizeTier}))};
}


